<?php require 'functions.php';$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.id=?');$s->execute([$id]);$p=$s->fetch();if(!$p){http_response_code(404);exit('Produk tidak ditemukan');}$related=recommend_products($pdo,$id,4);$pageTitle=$p['name'];if($_SERVER['REQUEST_METHOD']==='POST'){ $qty=max(1,(int)($_POST['qty']??1));if($qty>$p['stock']){flash('Jumlah melebihi stok.');go('product.php?id='.$id);}$_SESSION['cart'][$id]=min($p['stock'],($_SESSION['cart'][$id]??0)+$qty);flash('Produk ditambahkan ke keranjang.');go('cart.php');}require 'header.php';?><section class="detail"><img src="<?=e(image_url($p['image']))?>"><div><small class="eyebrow"><?=e($p['category_name']??'Handmade')?></small><h1><?=e($p['name'])?></h1><h2 class="price"><?=rupiah($p['price'])?></h2><p><?=nl2br(e($p['description']))?></p><p class="stock">Stok tersedia: <?=$p['stock']?></p><form method="post" class="buy-form"><?=csrf_field()?><input type="number" name="qty" value="1" min="1" max="<?=$p['stock']?>"><button class="btn" <?=$p['stock']<1?'disabled':''?>>Tambah ke Keranjang</button></form></div></section><section class="section"><h2>Produk yang mungkin kamu suka</h2><div class="products"><?php foreach($related as $r):?><article class="product"><a href="<?=url('product.php?id='.$r['id'])?>"><img src="<?=e(image_url($r['image']))?>"></a><div class="product-info"><a class="product-name" href="<?=url('product.php?id='.$r['id'])?>"><?=e($r['name'])?></a><b><?=rupiah($r['price'])?></b></div></article><?php endforeach;?></div></section><?php require 'footer.php';?>